import { FC, useLayoutEffect, useMemo, useRef } from 'react';

import { Chart, ChartData } from 'chart.js';
import { BasicContainer, NoDataYet, Skeleton } from 'components';
import { CHART_CONSTANTS } from 'components/Chart/Bar/SimpleBarChart/constants/constants';
import { registerChartModules } from 'components/Chart/register';
import { ErrorContainer } from 'components/Error/Error';

import { POS_CONTENT_MIN_HEIGHT_PX } from './constants';
import { usePosBleedLineSync } from './hooks';
import {
  StyledContainer,
  StyledNoDataContainer,
} from './PosPerformance.styles';
import { PosPerformanceChartView } from './PosPerformanceChartView';
import type {
  PosPerformanceBarDataset,
  PosPerformanceProps,
} from './types/index';
import {
  buildPosPerformanceChartOptions,
  createPosBarSpacingPlugin,
  getSymmetricYScaleExtents,
} from './utils';

const EMPTY_LABELS: string[] = [];
const EMPTY_BAR_DATASETS: PosPerformanceBarDataset[] = [];

registerChartModules();

export const PosPerformance: FC<PosPerformanceProps> = ({
  dataTestId,
  chartData,
  isLoading,
  error,
  onRetry,
}) => {
  const chartRef = useRef<Chart<'bar'> | null>(null);
  const { shellRef, bleedLines, bleedSyncPlugin } = usePosBleedLineSync(
    chartRef,
    dataTestId,
  );

  const labels = chartData?.labels ?? EMPTY_LABELS;
  const barDatasets = chartData?.datasets ?? EMPTY_BAR_DATASETS;
  const comparisonRows = chartData?.comparison?.rows ?? [];

  const yScaleExtents = useMemo(
    () => getSymmetricYScaleExtents(barDatasets),
    [barDatasets],
  );

  const posBarSpacingPlugin = useMemo(
    () => createPosBarSpacingPlugin(() => shellRef.current),
    [],
  );

  useLayoutEffect(() => {
    if (!labels.length) {
      return;
    }
    const id = globalThis.requestAnimationFrame(() => {
      chartRef.current?.update('none');
    });
    return () => globalThis.cancelAnimationFrame(id);
  }, [labels]);

  const barChartJsData: ChartData<'bar'> = useMemo(
    () => ({
      labels,
      datasets: barDatasets.map((dataset) => ({
        ...dataset,
        borderRadius: CHART_CONSTANTS.BORDER_RADIUS,
      })),
    }),
    [barDatasets, labels],
  );

  const options = useMemo(
    () => buildPosPerformanceChartOptions(yScaleExtents),
    [yScaleExtents],
  );

  const containerTestId = dataTestId
    ? `${dataTestId}-pos-performance`
    : undefined;
  const skeletonTestId = dataTestId
    ? `${dataTestId}-pos-performance-skeleton`
    : undefined;
  const noDataTestId = dataTestId
    ? `${dataTestId}-pos-performance-no-data`
    : undefined;

  if (isLoading && !chartData) {
    return (
      <Skeleton
        length={1}
        width="100%"
        height={`${POS_CONTENT_MIN_HEIGHT_PX}px`}
        borderRadius="large"
        dataTestId={skeletonTestId}
      />
    );
  }

  const showEmptyState = chartData === null || !labels.length;

  const renderContent = () => {
    if (error) {
      return (
        <StyledNoDataContainer $minHeight={POS_CONTENT_MIN_HEIGHT_PX}>
          <ErrorContainer
            title="We couldn't load this data"
            message="Something went wrong. Please try again."
            actions={Boolean(onRetry)}
            actionOne="Try again"
            handleActionOne={onRetry}
            dataTestId={
              dataTestId
                ? `${dataTestId}-pos-performance-error`
                : 'pos-performance-error'
            }
          />
        </StyledNoDataContainer>
      );
    }

    if (showEmptyState) {
      return (
        <StyledNoDataContainer $minHeight={POS_CONTENT_MIN_HEIGHT_PX}>
          <NoDataYet dataTestId={noDataTestId} />
        </StyledNoDataContainer>
      );
    }

    return (
      <PosPerformanceChartView
        chartData={chartData}
        dataTestId={dataTestId}
        chartRef={chartRef}
        shellRef={shellRef}
        bleedLines={bleedLines}
        barChartJsData={barChartJsData}
        options={options}
        posBarSpacingPlugin={posBarSpacingPlugin}
        bleedSyncPlugin={bleedSyncPlugin}
        labels={labels}
        comparisonRows={comparisonRows}
      />
    );
  };

  return (
    <BasicContainer
      header={{
        title: 'POS Performance',
        titleSize: 'H2',
      }}
      layout={{ bodyPadding: false, background: '#F9F9F9' }}
      dataTestId={containerTestId}
    >
      <StyledContainer>{renderContent()}</StyledContainer>
    </BasicContainer>
  );
};
